True def transform(grid):
    fill_by_outline = {1: 7, 5: 2, 6: 2, 4: 7}
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for color, fill in fill_by_outline.items():
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if (r1-r0 == c1-c0 and r1-r0 >= 2 and
            all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1)) and
            all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1))):
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    if grid[r][c] != color:
                        out[r][c] = fill
    return out
